/**
 * Call by ROM address. The address need not be a routine's first
 * instruction: the ROM jumps into the middle of routines, so this finds
 * the routine containing the address and enters it there.
 */
export function call(addr: number, m: Machine): void {
  // a halted chip does not start another routine
  if (m.stopped) return;
  let at = addr >>> 0;
  // A routine that runs off its own end has jumped, not called.
  // Continuing here keeps that flat, the way it is on the chip.
  for (;;) {
  try {
  const a = at;
  let lo = 0;
  let hi = STARTS.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (STARTS[mid] <= a) { found = mid; lo = mid + 1; } else { hi = mid - 1; }
  }
  if (found < 0 || a >= ENDS[found]) {
    // stubbing only ever applies outside the overlay - a call
    // through an uninitialised pointer into hardware space. An
    // address inside the overlay is real code that failed to get
    // ported, and swallowing it hides the gap.
    if (m.stubMissing && a >= 0x20000) { m.missingCalls.push(a); return; }
    throw new Error('no routine covers 0x' + a.toString(16));
  }
  m.jump = 0;
  if (m.onCall) {
    const before = m.a7 >>> 0;
    FNS[found](m, a);
    m.onCall(a, before, m.a7 >>> 0);
  } else {
    FNS[found](m, a);
  }
  if (!m.jump) return;
  at = m.jump; m.jump = 0;
  continue;
  } catch (e) {
    // An odd word access is an address error: the chip stacks a
    // seven-word frame and vectors through 0x0C. The transfer of
    // control cannot happen inside the instruction, so it is
    // raised there and turned into the exception here.
    if (e instanceof PendingInterrupt) throw e;
    if (!(e instanceof AddressError)) throw e;
    call(m.addressErrorFrame(), m);
    return;
  }
  }
}

